#!/usr/bin/env python3
"""scriptdoctor: 诊断脚本的 shebang/CRLF/BOM/可执行位/解释器路径问题。"""
import os
import shutil
import sys

def diagnose(path):
    issues = []
    if not os.path.isfile(path):
        return [f"文件不存在: {path}"]
    # 1) shebang
    with open(path, "rb") as f:
        first = f.read(16)
    if not first.startswith(b"#!"):
        issues.append("MISSING shebang")
    else:
        interp_line = first.split(b"\n")[0].decode("utf-8", "replace")
        interp = interp_line[2:].strip().split()
        if interp:
            cmd = interp[0]
            if cmd.startswith("/usr/bin/env") and len(interp) >= 2:
                cmd = interp[1]
            found = shutil.which(cmd)
            if not found:
                issues.append(f"INTERPRETER not in PATH: {cmd}")
            else:
                issues.append(f"INTERPRETER ok: {found}")
    # 2) CRLF
    with open(path, "rb") as f:
        data = f.read()
    if b"\r\n" in data:
        issues.append("HAS CRLF line terminators")
    # 3) UTF-8 BOM
    if data.startswith(b"\xef\xbb\xbf"):
        issues.append("HAS UTF-8 BOM")
    # 4) 可执行位
    if not os.access(path, os.X_OK):
        issues.append("NOT executable")
    else:
        issues.append("EXECUTABLE ok")
    return issues

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 scriptdoctor.py <script> [script ...]")
        sys.exit(1)
    all_clean = True
    for p in sys.argv[1:]:
        issues = diagnose(p)
        print(f"\n=== {p} ===")
        for i in issues:
            print(f"  {i}")
            if any(k in i for k in ["MISSING", "CRLF", "BOM", "NOT executable", "not in PATH"]):
                all_clean = False
    print("\n" + ("ALL CLEAN" if all_clean else "ISSUES FOUND"))

#!/usr/bin/env python3
"""Todo API: 基于 http.server 的内存态 REST API。"""
import json
import re
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler

TODOS = []
NEXT_ID = 1

class TodoHandler(BaseHTTPRequestHandler):
    def _json(self, code, obj):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self):
        n = int(self.headers.get("Content-Length", 0))
        raw = self.rfile.read(n) if n else b""
        try:
            return json.loads(raw)
        except Exception:
            return None

    def do_GET(self):
        m = re.match(r"/todos/(\d+)", self.path)
        if m:
            tid = int(m.group(1))
            for t in TODOS:
                if t["id"] == tid:
                    return self._json(200, t)
            return self._json(404, {"error": "not found"})
        return self._json(200, {"todos": TODOS})

    def do_POST(self):
        global NEXT_ID
        if self.path.rstrip("/") != "/todos":
            return self._json(404, {"error": "not found"})
        body = self._read_body()
        if not body or "title" not in body:
            return self._json(400, {"error": "title required"})
        todo = {"id": NEXT_ID, "title": body["title"], "done": False}
        NEXT_ID += 1
        TODOS.append(todo)
        return self._json(201, todo)

    def do_PUT(self):
        m = re.match(r"/todos/(\d+)", self.path)
        if not m:
            return self._json(404, {"error": "not found"})
        tid = int(m.group(1))
        body = self._read_body()
        if body is None:
            return self._json(400, {"error": "bad json"})
        for t in TODOS:
            if t["id"] == tid:
                t.update({k: v for k, v in body.items() if k in ("title", "done")})
                return self._json(200, t)
        return self._json(404, {"error": "not found"})

    def do_DELETE(self):
        global TODOS
        m = re.match(r"/todos/(\d+)", self.path)
        if not m:
            return self._json(404, {"error": "not found"})
        tid = int(m.group(1))
        for i, t in enumerate(TODOS):
            if t["id"] == tid:
                TODOS.pop(i)
                return self._json(200, {"deleted": tid})
        return self._json(404, {"error": "not found"})

if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 18090
    server = HTTPServer(("127.0.0.1", port), TodoHandler)
    print(f"Todo server on :{port}", flush=True)
    server.serve_forever()
